query Query($where: MaintenanceChecklistWhereInput, $orderBy: [MaintenanceChecklistOrderByInput!], $first: Int, $after: String) {
  maintenanceChecklist(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        number
        description
      }
    }
  }
}

query Query($where: MaintenanceChecklistTaskWhereInput, $orderBy: [MaintenanceChecklistTaskOrderByInput!], $first: Int, $after: String) {
  maintenanceChecklistTask(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        createFollowUpOnFail
        expectedHours
        followUpChecklist {
         id
         number
    }
        active
        createFollowUp
        createFollowUpOnFail
        required
        description
        instructions
        order
        maxValue {
          value
          unitId
          unit {
            id
            unitType {
              id
            }
            name
            code
          }
        }
        minValue {
          value
          unitId
          unit {
            id
            unitType {
              id
            }
            name
            code
          }
        }

        maintenanceItemId
        maintenanceItem {
          id
          name
        }
      }
    }
  }
}

